const years=[2020,2021,2022,2023,2024,2025];
const data=[['Lederwaren','Lederhandtasche · Medium',2800,4900,'bag'],['Uhren','Mechanische Armbanduhr',6500,9100,'watch'],['Mobilität','Sportcoupé · Basisausstattung',98000,129000,'car'],['Reisen & Genuss','Degustationsmenü · 8 Gänge',185,295,'food'],['Lederwaren','Reisekoffer · Kabinenformat',720,1100,'case'],['Uhren','Dresswatch · Edelstahl',4200,5700,'watch'],['Mobilität','Premium-SUV · Basismodell',62000,81000,'car'],['Reisen & Genuss','Stadthotel · Doppelzimmer',320,460,'hotel'],['Reisen & Genuss','Champagner · 0,75 l',48,69,'bottle'],['Reisen & Genuss','Ferienhotel · Halbpension',410,590,'hotel'],['Bildung & Service','Privatschule · Jahresgebühr',15000,18300,'book'],['Bildung & Service','Golfclub · Jahresbeitrag',1900,2450,'golf'],['Lederwaren','Lederschuhe · rahmengenäht',480,650,'shoe'],['Bildung & Service','Fitnessclub · Jahresbeitrag',1440,1860,'golf'],['Mobilität','Premium-Fahrrad',2800,3600,'bike'],['Bildung & Service','Sprachunterricht · 10 Stunden',600,760,'book']].map((p,i)=>({id:'demo-'+String(i+1).padStart(2,'0'),category:p[0],name:p[1],icon:p[4],prices:[p[2],Math.round(p[2]*1.04),Math.round(p[2]+(p[3]-p[2])*.38),Math.round(p[2]+(p[3]-p[2])*.66),Math.round(p[2]+(p[3]-p[2])*.87),p[3]],currency:'EUR',tax:'inkl. angenommener Umsatzsteuer',priceType:'synthetischer Beispielpreis',source:null,status:'DEMO_UNGEPRUEFT',version:'0.1'}));
const vpi=[100,103.2,110.4,117,119.6,122.1];let start=0,category='Alle',query='';const $=s=>document.querySelector(s);const fmt=(x,n=1)=>x.toLocaleString('de-DE',{minimumFractionDigits:n,maximumFractionDigits:n});const eur=x=>x.toLocaleString('de-DE',{style:'currency',currency:'EUR',maximumFractionDigits:0});const pct=x=>'+'+fmt(x)+' %';const series=()=>years.slice(start).map((_,j)=>100*data.reduce((a,p)=>a+p.prices[start+j]/p.prices[start],0)/data.length);
const shapes={bag:'<path d="M65 50h95l9 65H56z" fill="#645244"/><path d="M88 52V34q25-29 49 0v18" fill="none" stroke="#4b3f36" stroke-width="7"/><path d="M61 67h103" stroke="#b69b7d"/><rect x="103" y="66" width="17" height="13" rx="2" fill="#c1ac79"/>',watch:'<rect x="97" y="4" width="34" height="132" rx="9" fill="#9a9b8e"/><path d="M101 5v130m26-130v130" stroke="#d6d7cd" stroke-width="7"/><circle cx="114" cy="70" r="34" fill="#c4c5b9" stroke="#81897b" stroke-width="3"/><circle cx="114" cy="70" r="27" fill="#283d31"/><path d="M114 49v22l16 11" fill="none" stroke="#ded8b8" stroke-width="2"/><circle cx="114" cy="70" r="2" fill="#d6d0b6"/>',car:'<path d="M27 90l15-21 48-8 30-25h43l27 32 26 9 8 23H24z" fill="#a9b3a5" stroke="#778574"/><path d="M102 61l23-21h34l18 22z" fill="#394f43"/><circle cx="63" cy="98" r="16" fill="#29342b"/><circle cx="63" cy="98" r="9" fill="#bec4b7"/><circle cx="183" cy="98" r="16" fill="#29342b"/><circle cx="183" cy="98" r="9" fill="#bec4b7"/>',food:'<ellipse cx="115" cy="75" rx="70" ry="49" fill="#fff" stroke="#d8dbcf"/><ellipse cx="115" cy="75" rx="51" ry="34" fill="#f0eee4"/><path d="M94 83q-20-30 16-31l27 14-9 26z" fill="#ae7255"/><path d="M100 55l28 29m-34-8l36-19" stroke="#688251" stroke-width="5"/><circle cx="141" cy="76" r="8" fill="#b19b55"/>',case:'<rect x="78" y="26" width="72" height="96" rx="10" fill="#a6a99a" stroke="#717f6c"/><path d="M99 25V13h30v12m-37 15v69m15-69v69m15-69v69m15-69v69" fill="none" stroke="#d4d8cb" stroke-width="3"/>',hotel:'<path d="M52 119V30h127v89z" fill="#c2bba5"/><path d="M40 30l76-23 76 23" fill="#647561"/><path d="M70 45h20v22H70zm37 0h20v22h-20zm37 0h20v22h-20zM70 81h20v22H70zm74 0h20v22h-20z" fill="#586b58"/><path d="M106 120V86h22v34" fill="#847c65"/>',bottle:'<path d="M106 10h19v37l15 20v58H90V67l16-20z" fill="#405b3b"/><path d="M106 10h19v34h-19z" fill="#c4b685"/><path d="M91 80h48v30H91z" fill="#d4c79b"/><text x="115" y="99" text-anchor="middle" fill="#516146" font-size="10">CUVÉE</text>',book:'<path d="M51 37l64 13 64-13v78l-64 15-64-15z" fill="#b8b6a0"/><path d="M55 28l60 16 60-16v77l-60 16-60-16z" fill="#e4dfcc"/><path d="M115 44v77m-50-77l40 10m-40 5l40 10m-40 5l40 10m20-30l40-10m-40 25l40-10m-40 25l40-10" stroke="#9ba48c" fill="none"/>',golf:'<ellipse cx="116" cy="112" rx="68" ry="17" fill="#bbc9a6"/><path d="M119 110V20l42 13-42 14" fill="#5b7650" stroke="#597044" stroke-width="3"/><circle cx="88" cy="107" r="10" fill="#fff"/>',shoe:'<path d="M53 91l28-49 37 19 17 24 49 12q21 6 13 23H51q-12-9 2-29" fill="#7c5c43"/><path d="M54 117h140M89 60l30 12m-36-4l39 13m-43-5l48 14" stroke="#c1a689" stroke-width="3"/>',bike:'<g fill="none" stroke="#73856b" stroke-width="3"><circle cx="62" cy="98" r="28"/><circle cx="173" cy="98" r="28"/><path d="M62 98l36-51 29 51H62l35-42h56l20 42m-46 0l26-59 15-8m-82 16h25"/></g>'};
function art(type){return '<svg viewBox="0 0 230 145" aria-hidden="true">'+(shapes[type]||shapes.bag)+'</svg>'}
function chart(a,b,large=false){const w=1040,h=large?210:245,left=35,right=70,top=15,bottom=28,max=Math.ceil(Math.max(...a,...b)/10)*10,min=100;const x=i=>left+i*(w-left-right)/(a.length-1),y=v=>h-bottom-(v-min)/(max-min||10)*(h-bottom-top);const path=v=>v.map((p,i)=>(i?'L':'M')+x(i)+','+y(p)).join(' ');let grid='';for(let v=100;v<=max;v+=10)grid+=`<line x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}" stroke="#e9ede4" stroke-dasharray="3 5"/><text x="8" y="${y(v)+3}">${v}</text>`;return `<svg role="img" aria-label="Jährliche synthetische Preisreihen ab ${years[start]}, Basis 100" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">${grid}<path d="${path(a)} L${x(a.length-1)},${h-bottom} L${left},${h-bottom}Z" fill="#edf3e9" opacity=".7"/><path d="${path(b)}" fill="none" stroke="#a3ac9e" stroke-width="2.5"/><path d="${path(a)}" fill="none" stroke="#467253" stroke-width="3"/>${a.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="3.5" fill="white" stroke="#467253" stroke-width="2"/>`).join('')}${years.slice(start).map((v,i)=>`<text text-anchor="middle" x="${x(i)}" y="${h-5}">${v}</text>`).join('')}<text x="${w-right+12}" y="${y(a.at(-1))+4}" style="fill:#467253;font-weight:700">${fmt(a.at(-1))}</text><text x="${w-right+12}" y="${y(b.at(-1))+4}">${fmt(b.at(-1))}</text></svg>`}
function render(){const a=series(),b=vpi.slice(start).map(v=>v/vpi[start]*100),p=a.at(-1)-100,v=b.at(-1)-100;$('#premium').textContent=pct(p);$('#vpi').textContent=pct(v);$('#gap').textContent='+'+fmt(p-v)+' Pp.';$('.years').textContent=years[start]+'–2025';$('#baseLabel').textContent=`Indexiert auf ${years[start]} = 100 · Synthetische Demonstrationsdaten`;$('#chart').innerHTML=chart(a,b);renderCards()}
function renderCards(){const filtered=data.filter(p=>(category==='Alle'||p.category===category)&&p.name.toLowerCase().includes(query));$('#cards').innerHTML=filtered.map(p=>`<button class="card" data-id="${p.id}" aria-label="Details zu ${p.name}"><div class="art"><span class="tag">BEISPIELPOSITION</span>${art(p.icon)}</div><div class="cardinfo"><div class="category">${p.category}</div><h3>${p.name}</h3><div class="prices"><span><small>2025 · DEMOPREIS</small>${eur(p.prices[5])}</span><span class="change">${pct((p.prices[5]/p.prices[start]-1)*100)}</span></div><div class="cardbottom"><span>${years[start]}: ${eur(p.prices[start])}</span><span>Details ↗</span></div></div></button>`).join('');$('#empty').hidden=filtered.length>0;document.querySelectorAll('.card').forEach(c=>c.onclick=()=>show(c.dataset.id))}
function show(id){const p=data.find(p=>p.id===id),base=p.prices[start],now=p.prices[5],r=now/base-1,vr=vpi[5]/vpi[start]-1;$('#detailContent').innerHTML=`<div class="eyebrow">DEMO · ${p.category.toUpperCase()}</div><h2>${p.name}</h2><p>Illustrative Produktdefinition. Keine reale Marke oder geprüfte Preisbeobachtung. ID: ${p.id}.</p><div class="metrics"><article><div class="label">${years[start]}</div><div class="big">${eur(base)}</div></article><article><div class="label">2025</div><div class="big greenText">${eur(now)}</div></article></div><p><strong>${pct(r*100)} · ${eur(now-base)} mehr</strong><br>Annualisierte Veränderung: ${fmt((Math.pow(now/base,1/(5-start))-1)*100)} % p. a.<br>Bei Entwicklung wie die VPI-Beispielreihe: ${eur(base*(1+vr))}.</p><table><thead><tr><th>Jahr</th><th>Demopreis</th><th>Prüfstatus</th></tr></thead><tbody>${years.map((y,i)=>`<tr><td>${y}</td><td>${eur(p.prices[i])}</td><td>Ungeprüft · synthetisch</td></tr>`).join('')}</tbody></table><p>Preisart: synthetischer Beispielpreis. ${p.tax}. Quelle / Beleg / Abrufdatum: nicht vorhanden. Beobachtungsdatum: nicht vorhanden; Jahresangaben sind Modellperioden. Modellversion 0.1. Kein Qualitätswechsel modelliert.</p>`;$('#detail').showModal();location.hash='produkt/'+id}
$('#detail .close').onclick=()=>$('#detail').close();$('#detail').addEventListener('close',()=>{if(location.hash.startsWith('#produkt/'))history.replaceState(null,'','#warenkorb')});$('#detail').onclick=e=>{if(e.target===$('#detail'))$('#detail').close()};$('#period').onchange=e=>{start=+e.target.value;render()};$('#search').oninput=e=>{query=e.target.value.toLowerCase();renderCards()};const cats=['Alle',...new Set(data.map(p=>p.category))];$('#filters').innerHTML=cats.map((c,i)=>`<button class="${i?'':'selected'}" aria-pressed="${!i}">${c}</button>`).join('');document.querySelectorAll('#filters button').forEach(b=>b.onclick=()=>{category=b.textContent;document.querySelectorAll('#filters button').forEach(c=>{c.classList.toggle('selected',c===b);c.setAttribute('aria-pressed',c===b)});renderCards()});$('#export').onclick=()=>{const payload={disclaimer:'SYNTHETISCHE DEMODATEN. Keine recherchierten Preise. VPI ebenfalls synthetisch.',version:'0.1',years,reference:vpi,products:data};const u=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='nobelpreis-demodaten-v0.1.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};render();if(location.hash.startsWith('#produkt/')){const id=location.hash.split('/')[1];if(data.some(p=>p.id===id))show(id)}
